<?php $__env->startSection('content'); ?><div class="page-head"><div><div class="eyebrow">BUSINESS PROFILE</div><h1><?php echo e($business->name); ?></h1><p><?php echo e($business->contact_person); ?> · <?php echo e($business->email); ?></p></div><a class="btn secondary" href="<?php echo e(route('businesses.edit',$business)); ?>">Edit Business</a></div><div class="stats-grid three"><div class="stat-card"><div class="stat-label">Status</div><div class="stat-value small"><?php echo e(ucfirst($business->status)); ?></div></div><div class="stat-card"><div class="stat-label">Cards</div><div class="stat-value"><?php echo e($business->cards->count()); ?></div></div><div class="stat-card"><div class="stat-label">Recent Payments</div><div class="stat-value"><?php echo e($business->payments->count()); ?></div></div></div><div class="section-grid"><div class="panel"><div class="panel-head"><h3>Virtual Cards</h3><a href="<?php echo e(route('cards.create')); ?>">Create card →</a></div><div class="list"><?php $__empty_1 = true; $__currentLoopData = $business->cards; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $c): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><div class="list-row"><div><strong><?php echo e($c->reference); ?></strong><small><?php echo e($c->cardholder_name); ?></small></div><span class="badge <?php echo e($c->status->value==='active'?'success':'neutral'); ?>"><?php echo e(ucfirst($c->status->value)); ?></span><strong>₹<?php echo e(number_format($c->remaining_limit,2)); ?> left</strong></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><div class="empty">No cards.</div><?php endif; ?></div></div><div class="panel"><div class="panel-head"><h3>Business Details</h3></div><dl class="details"><dt>Phone</dt><dd><?php echo e($business->phone ?: '—'); ?></dd><dt>Address</dt><dd><?php echo e($business->address ?: '—'); ?></dd><dt>GST / Tax</dt><dd><?php echo e($business->tax_number ?: '—'); ?></dd><dt>Created</dt><dd><?php echo e($business->created_at->format('d M Y')); ?></dd></dl></div></div><?php $__env->stopSection(); ?>

